import{_ as n,l as r,o as a,c as l,v as e,p as d,x as i,d as s,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Robin Hood 与布谷","description":"","frontmatter":{"title":"Robin Hood 与布谷","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/robin-cuckoo.md","filePath":"cs/robin-cuckoo.md","lastUpdated":1789023840000}'),p={name:"cs/robin-cuckoo.md"};function E(A,o,_,B,b,m){const t=r("Mermaid");return a(),l("div",null,[o[1]||(o[1]=e('<h1 id="robin-hood-与布谷" tabindex="-1">Robin Hood 与布谷 <a class="header-anchor" href="#robin-hood-与布谷" aria-label="Permalink to &quot;Robin Hood 与布谷&quot;">​</a></h1><div class="epigraph"><p>线性探测会聚集；Robin Hood 让探测距离更齐，布谷用两个表把插入变成踢人，最坏查找可以钉成常数次探测。</p><footer>—— 据 Celis, Larson and Munro, Robin Hood Hashing, FOCS 1985；Pagh and Rodler, Cuckoo Hashing, ESA 2001 / J. Algorithms 2004 整理</footer></div><p><a href="/cs/chaining-open-address">上一课</a>钉了链与开放寻址，点名线性探测聚集，并声明不引入 Cuckoo。本课不重讲 \\(\\alpha\\) 与墓碑。缺口是两种把开放寻址的探测长度压住的策略：Robin Hood 按「已走距离」抢槽；布谷散列每个键两个候选位置，插入时踢走占用者。跳表与布隆在后课，本课仍是字典的放置策略。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>线性探测成功查找的期望随 \\(\\alpha/(1-\\alpha)\\) 涨，聚集让方差很大：个别键探测很长。缺口不是换 \\(h(k)\\)——上一课函数已经均匀——而是<strong>插入时重排已有键的位置</strong>。Robin Hood：比较当前键的探测距离与槽内键的距离，远者抢槽，被抢的继续探测。查找仍沿探测序列，但最长探测距离更短、更齐。</p><p>布谷：两个散列 \\(h_1,h_2\\)，键只住两处之一。查找最多两次。插入把占用者踢到它的另一处，可能连环；过长则再散列。</p><p><span class="marginnote">布谷的「两个巢」来自布谷鸟占巢的比喻。负载通常要留空（\\(\\alpha\\) 明显小于 1），否则踢链失败频繁。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Robin Hood：开放寻址 + 每槽记录或可重算的探测距离；插入时若 <code>dist(新) &gt; dist(住户)</code> 则交换。删除仍要墓碑或反向回填，回填比普通线性探测更要小心距离。</p><p>布谷：查 \\(h_1(k)\\) 与 \\(h_2(k)\\)。插：若有空则放入；否则踢出其中一个，令其去另一表对应槽，循环直到空槽或踢次数上限。</p>',10)),(a(),d(c,null,{default:i(()=>[h(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20RH%5B%22Robin%20Hood%EF%BC%9A%E8%B7%9D%E7%A6%BB%E5%A4%A7%E7%9A%84%E6%8A%A2%E6%A7%BD%22%5D%20--%3E%20OA%5B%22%E4%BB%8D%E6%98%AF%E4%B8%80%E6%9D%A1%E6%8E%A2%E6%B5%8B%E5%BA%8F%E5%88%97%22%5D%0A%20%20CU%5B%22%E5%B8%83%E8%B0%B7%EF%BC%9A%E4%B8%A4%E6%A7%BD%E4%B9%8B%E4%B8%80%22%5D%20--%3E%20KICK%5B%22%E6%8F%92%E5%85%A5%E8%B8%A2%E9%93%BE%22%5D%0A%20%20CU%20--%3E%20LOOK%5B%22%E6%9F%A5%E6%89%BE%20%E2%89%A4%202%20%E6%AC%A1%E6%8E%A2%E6%B5%8B%22%5D%0A"})]),fallback:i(()=>[...o[0]||(o[0]=[s(" Loading... ",-1)])]),_:1})),o[2]||(o[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>两者都改善尾部延迟，服务最坏探测比 plain 线性探测稳。Robin Hood 对 cache 仍友好（顺序探测）。布谷查找探测次数有硬上限，适合要最坏界限的硬件转发表；插入可能失败需重建，合同是「期望插入成功，失败则再散列」。</p><p>与链地址：\\(\\alpha\\gt 1\\) 仍只有链轻松支持。这两种都要求表内有空槽。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Hopscotch、不把密码学哈希当必须。布隆过滤器下一课：<strong>不是字典</strong>，不存键本身，允许假阳性。并发 cuckoo 的位移序列是附录。</p><p>后课默认：开放寻址可用 Robin Hood 或布谷压探测尾部。只需「可能在/一定不在」且省空间，用布隆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Robin Hood 均衡探测距离；布谷把查找钉在两个位置。</li><li>插入可能重排或再散列；\\(\\alpha\\) 不能顶满。</li><li>布隆过滤器是下一课的近似集，不是精确字典。</li><li>出处：Celis et al., <em>FOCS</em>, 1985；Pagh and Rodler, <em>J. Algorithms</em>, 2004；对照 CLRS 开放寻址。</li></ul>',8))])}const k=n(p,[["render",E]]);export{f as __pageData,k as default};
